import "./StatusMessage.css";

export interface StatusMessageProps {
  text: string;
  onDismiss: () => void;
}

export function StatusMessage({ text, onDismiss }: StatusMessageProps) {
  return (
    <div className="status-message">
      <p className="status-message__text" role="status" aria-live="polite" aria-atomic="true">
        {text}
      </p>
      <button type="button" className="status-message__dismiss" onClick={onDismiss}>
        Dismiss
      </button>
    </div>
  );
}
```

```css
.status-message {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  max-width: 100%;
  padding: 0.5rem 0.5rem 0.5rem 1rem;
  border: 1px solid var(--myelin);
  border-left-width: 4px;
  border-radius: 0.75rem;
  background: var(--myelin-wash);
  color: var(--ink);
  font: inherit;
  animation: status-message-in 200ms ease-out;
}

.status-message__text {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  font-size: clamp(0.875rem, 0.8rem + 0.3vw, 1rem);
  overflow-wrap: anywhere;
}

.status-message__dismiss {
  flex: none;
  font: inherit;
  font-size: 0.875rem;
  padding: 0.25rem 0.75rem;
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--ink);
  border-radius: 999px;
  cursor: pointer;
}

.status-message__dismiss:hover {
  background: var(--slide);
}

@keyframes status-message-in {
  from {
    opacity: 0;
    transform: translateY(0.25rem);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

:root[data-motion="reduce"] .status-message,
:root[data-motion="reduce"] .status-message__dismiss {
  animation: none;
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .status-message,
  .status-message__dismiss {
    animation: none;
    transition: none;
  }
}
```

